def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    if not isinstance(value, timedelta):
        raise TypeError(f"Expected datetime.timedelta, got {type(value).__name__}")
    return value.total_seconds()

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    return value.isoformat()

def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value: The point instance to dehydrate.
    :type value: Point
    :return: A dictionary representation of the point's coordinates.
    """
    # If the point has a custom to_dict method, use that
    if hasattr(value, 'to_dict'):
        return value.to_dict()
    # Otherwise, attempt to collect common coordinate attributes
    attrs = {}
    for key in ('x', 'y', 'z'):
        if hasattr(value, key):
            attrs[key] = getattr(value, key)
    # Fallback: use the object's __dict__ if no known attributes are found
    if not attrs and hasattr(value, '__dict__'):
        return dict(value.__dict__)
    return attrs

