def unit_of_work(metadata=None, timeout=None):
    from functools import wraps

    def decorator(tx_callable):
        @wraps(tx_callable)
        def wrapper(session, *args, **kwargs):
            # Build transaction configuration
            config = {}
            if metadata is not None:
                config["metadata"] = metadata
            if timeout is not None:
                if timeout < 0:
                    raise ValueError("timeout must be non‑negative")
                config["timeout"] = timeout

            # Execute the function inside a managed transaction
            if config:
                return session.write_transaction(tx_callable, *args, **kwargs, config=config)
            else:
                return session.write_transaction(tx_callable, *args, **kwargs)

        return wrapper

    return decorator

def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    for i, item in enumerate(self):
        if item == key:
            return i
    raise ValueError(f"{key} is not in the sequence")

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.
    """
    # If no filtering keys were supplied, return all values in order
    if not keys:
        # Prefer a dedicated _values attribute if present
        if hasattr(self, "_values"):
            return list(self._values)
        # Otherwise fall back to a mapping or attributes
        if isinstance(self, dict):
            return list(self.values())
        # Finally, gather public attributes
        return [v for k, v in vars(self).items() if not k.startswith("_")]

    # Build a list of values based on provided keys or indexes
    result = []

    # Attempt to use internal ordering if available
    if hasattr(self, "_keys") and hasattr(self, "_values"):
        key_to_val = dict(zip(self._keys, self._values))
        for selector in keys:
            if isinstance(selector, int):
                # Handle negative indices as well
                sz = len(self._values)
                if -sz <= selector < sz:
                    result.append(self._values[selector])
            else:
                if selector in key_to_val:
                    result.append(key_to_val[selector])
        return result

    # Fallback for mapping-like objects
    if isinstance(self, dict):
        values_list = list(self.values())
        for selector in keys:
            if isinstance(selector, int):
                if -len(values_list) <= selector < len(values_list):
                    result.append(values_list[selector])
            else:
                if selector in self:
                    result.append(self[selector])
        return result

    # Fallback for generic objects with public attributes
    attrs = {k: v for k, v in vars(self).items() if not k.startswith("_")}
    values_list = list(attrs.values())
    for selector in keys:
        if isinstance(selector, int):
            if -len(values_list) <= selector < len(values_list):
                result.append(values_list[selector])
        else:
            if selector in attrs:
                result.append(attrs[selector])

    return result

def data(self, *keys):
    """Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # If no keys specified return the whole record as a dict
    if not keys:
        return dict(zip(self.keys(), self))

    keys_list = list(self.keys())
    result = {}

    for key in keys:
        if isinstance(key, int):
            # Path: index access
            if key < 0 or key >= len(keys_list):
                raise IndexError(f"index {key} out of bounds for record of length {len(keys_list)}")
            result[keys_list[key]] = self[key]
        else:
            # Path: key access
            if key in keys_list:
                idx = keys_list.index(key)
                result[key] = self[idx]
            else:
                result[key] = None
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None, hydration_hooks=None, **handlers):
    """Appends a DISCARD message to the output queue."""
    # Normalize the parameters.
    try:
        n = int(n)
    except Exception:
        n = -1
    try:
        qid = int(qid)
    except Exception:
        qid = -1

    # Merge provided hooks with the instance defaults.
    if dehydration_hooks is None:
        dehydration_hooks = getattr(self, "_dehydration_hooks", {})
    if hydration_hooks is None:
        hydration_hooks = getattr(self, "_hydration_hooks", {})

    # Build the message dictionary that the write protocol expects.
    message = {
        "command": "DISCARD",
        "count": n,
        "qid": qid,
        "dehydration_hooks": dehydration_hooks,
        "hydration_hooks": hydration_hooks,
    }

    # Write the message into the outgoing buffer.
    # The library is assumed to expose a _write method that serialises a dict
    # using PackStream or a similar protocol.
    if hasattr(self, "_write"):
        self._write(message)
    else:
        # As a fallback, use a generic queue to hold outgoing messages.
        if not hasattr(self, "_queue"):
            self._queue = []
        self._queue.append(message)

    # Return a Response object that will trigger when the server replies
    # to this DISCard message.  The concrete implementation of Response
    # is part of the larger library; we just instantiate it with the
    # provided handlers.
    response_cls = getattr(self, "Response", type(None))
    return response_cls(on_success=handlers.get("success"),
                        on_error=handlers.get("error"),
                        on_retry=handlers.get("retry"))

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    # Build the BEGIN message parameters
    params = {}
    if mode is not None:
        if mode not in ("READ", "WRITE"):
            raise ValueError("mode must be either 'READ' or 'WRITE'")
        params["mode"] = mode
    else:
        params["mode"] = "WRITE"

    if bookmarks is not None:
        # Ensure we have a list of strings
        params["bookmarks"] = [str(b) for b in bookmarks]
    else:
        params["bookmarks"] = []

    if metadata is not None:
        if not isinstance(metadata, dict):
            raise TypeError("metadata must be a dict")
        params["metadata"] = metadata

    if timeout is not None:
        params["timeout"] = int(timeout)
    if db is not None:
        params["database"] = str(db)
    if imp_user is not None:
        params["impersonatedUser"] = str(imp_user)

    # Store hooks on the session (used by packstream serializers/deserializers)
    if dehydration_hooks is not None:
        self._dehydration_hooks = dehydration_hooks
    if hydration_hooks is not None:
        self._hydration_hooks = hydration_hooks

    # Create and send the BEGIN packet (Bolt protocol CID = 0x00 for BEGIN)
    # We assume there is a packet helper that serialises the dict according to
    # Bolt's PackStream and writes it to the channel.
    packet = self._make_packet(self._CODE_BEGIN, params)
    self._channel.write(packet)
    self._channel.flush()

    # Return a Response object associated with this transaction.
    # The Response will close the transaction when it finishes.
    return Response(self._channel, handlers=handlers)

def point_type(name, fields, srid_map):
    """
    Dynamically create a Point subclass with custom attributes and optional SRID support.
    """
    # Default attribute values for the new class
    attrs = {field: None for field in fields}
    # Store SRID mapping as a class attribute
    attrs['_srid_map'] = srid_map

    # Custom initializer to inject field values
    def __init__(self, x, y, srid=None, **kwargs):
