    attrs['__init__'] = __init__

    # Create the new subclass dynamically
    return type(name, (Point,), attrs)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    import warnings
    import functools

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper

    return decorator

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    import os, sys, shutil
    if not cmd:
        return cmd
    if os.name != 'nt':
        return cmd
    executable = cmd[0]
    # Skip native Windows executables or scripts
    _, ext = os.path.splitext(executable)
    if ext.lower() in {'.exe', '.bat', '.cmd', '.com'}:
        return cmd
    if not os.path.isfile(executable):
        return cmd
    try:
        with open(executable, 'rb') as f:
            first_line = f.readline().decode(errors='ignore')
    except Exception:
        return cmd
    if not first_line.startswith('#!'):
        return cmd
    # Resolve shebang interpreter path
    interpreter = first_line[2:].strip().split()[0]
    interpreter_path = shutil.which(interpreter)
    if interpreter_path is None:
        interpreter_path = sys.executable
    # Construct new command to run the script via the interpreter
    new_cmd = (interpreter_path, executable) + cmd[1:]
    return new_cmd

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Compute cache key
            k = key(*args, **kwargs) if callable(key) else key
            # Retrieve from cache if present
            if lock is not None:
                with lock:
                    if k in cache:
                        return cache[k]
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result
            else:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm."""
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")

    def decorator(func):
        cache = {}
        freq = {}

        def wrapper(*args, **kwargs):
            try:
                key_args = args
                key_kwargs = tuple(sorted(kwargs.items()))
                if typed:
                    key = (key_args, key_kwargs, tuple(map(type, key_args)),
                           tuple(type(v) for _, v in key_kwargs))
                else:
                    key = (key_args, key_kwargs)
            except TypeError:
                # Unhashable argument; bypass cache
                return func(*args, **kwargs)

            if key in cache:
                # Increment hit count
                freq[key] += 1
                return cache[key]

            # Cache miss; compute result
            result = func(*args, **kwargs)

            if len(cache) >= maxsize:
                # Find least frequently used key(s)
                min_freq = min(freq.values())
                # Evict one key with the lowest frequency
                for k in list(freq):
                    if freq[k] == min_freq:
                        del cache[k]
                        del freq[k]
                        break

            cache[key] = result
            freq[key] = 1
            return result

        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__module__ = func.__module__
        return wrapper

    return decorator

def cachedmethod(cache, key=hashkey, lock=None):
    """
    Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            if lock:
                lock.acquire()
            try:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result
            finally:
                if lock:
                    lock.release()
        return wrapper
    return decorator

