@classmethod
    def _reset_logging(cls):
        """
        Reset the logging configuration to its default state by removing and
        closing all handlers attached to the root logger.
        """
        root_logger = logging.getLogger()
        # Close and remove each handler safely
        for handler in root_logger.handlers[:]:
            try:
                handler.flush()
            except Exception:
                pass
            try:
                handler.close()
            except Exception:
                pass
            root_logger.removeHandler(handler)
        # Explicitly clear the handlers list
        root_logger.handlers = []
        # Reset the lastResort logger if it is set
        if hasattr(logging, "lastResort"):
            logging.lastResort = None

