def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    # Try a direct attribute first
    if hasattr(object, "__provides__"):
        return object.__provides__
    # If the object is an instance, check its class
    try:
        return type(object).__provides__
    except AttributeError:
        pass
    # Fallback for older versions that use __interfaces__
    if hasattr(object, "__interfaces__"):
        return object.__interfaces__
    if hasattr(type(object), "__interfaces__"):
        return type(object).__interfaces__
    # No interfaces reported
    return {}

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for elem in sequence:
        # Expand nested tuples or lists to individual elements
        if isinstance(elem, (tuple, list)):
            output.extend(elem)
        else:
            output.append(elem)
    return output

