def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Cache computed indices for efficiency
    if not hasattr(self, "_err_indices_cache"):
        self._err_indices_cache = {}
    if coord_name in self._err_indices_cache:
        return self._err_indices_cache[coord_name]

    # Attempt to retrieve the error array associated with the coordinate.
    # Expect attribute naming convention: <coord_name>_err
    err_attr = f"{coord_name}_err"
    coord_err = getattr(self, err_attr, None)

    if coord_err is None:
        # No error array found; return empty index array
        indices = np.array([], dtype=int)
    else:
        # For numpy arrays or masked arrays, compute indices where
        # error values are not finite (NaN or inf).
        if isinstance(coord_err, (np.ndarray, np.ma.MaskedArray)):
            indices = np.nonzero(~np.isfinite(coord_err))[0]
        else:
            # If the error attribute is not array-like, default to empty
            indices = np.array([], dtype=int)

    # Store in cache before returning
    self._err_indices_cache[coord_name] = indices
    return indices

def _update_context(self, context):
    """
    Update *context* with the properties of this graph.

    Append indices to *context.error* for each error attribute of the graph.
    Existing values in *context.value* and its subcontexts are preserved.
    """
    # Ensure the context has an error dictionary
    if not hasattr(context, 'error') or context.error is None:
        context.error = {}

    # Start counting from the current number of errors
    next_index = len(context.error)

    # Inspect all attributes that represent errors
    for attr_name in dir(self):
        if not attr_name.startswith('error_'):
            continue

        # Derive a simplified error key (e.g., 'error_E_low' → 'x_low')
        # Attempt to map coordinate names to 'x', 'y', 'z' if such mapping exists.
        # Default to the attribute name without 'error_'.
        base_key = attr_name[6:]
        # Try to replace the first coordinate letter if it exists in the graph
        # This is a heuristic; if the graph defines coordinates, its first three
        # are considered x, y, z respectively.
        try:
            coord_names = getattr(self, 'coordinates')
        except AttributeError:
            coord_names = []

        # Replace a leading coordinate name with 'x', 'y', or 'z'
        if isinstance(coord_names, (list, tuple)) and coord_names:
            for idx, coord in enumerate(coord_names[:3]):
                if base_key.startswith(coord):
                    base_key = base_key.replace(coord, chr(ord('x') + idx), 1)
                    break

        # Lowercase the key
        err_key = base_key.lower()

        # Append the error index if this key is not already recorded
        if err_key not in context.error:
            context.error[err_key] = {"index": next_index}
            next_index += 1
    # Note: values in context.value are intentionally not modified.

