def difference(d1, d2, level=-1):
    """
    Return a dictionary containing items from *d1* that are not present
    in *d2*.  Recursively compares nested dictionaries up to *level*
    depths.  For infinite recursion, *level* should be set to ``-1``.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        return {}
    result = {}
    for key, val in d1.items():
        if key not in d2:
            result[key] = val
            continue
        other = d2[key]
        # If both values are dictionaries, recurse if depth allows
        if isinstance(val, dict) and isinstance(other, dict):
            # Decide whether to recurse
            if level != 0:
                new_depth = level - 1 if level > 0 else level
                subdiff = difference(val, other, new_depth)
                if subdiff:
                    result[key] = subdiff
            else:
                # depth exhausted; use dictionary equality check
                if val != other:
                    result[key] = val
        else:
            # Primitive values or mismatched types
            if val != other:
                result[key] = val
    return result

def _validate_labels(labels):
    import re
    key_pattern = re.compile(r'^[a-zA-Z0-9_]+$')
    val_pattern = re.compile(r'^[a-zA-Z0-9_]+$')
    errors = []

    def _validate_value(value, key_prefix):
        if isinstance(value, list):
            for idx, item in enumerate(value):
                _validate_value(item, f"{key_prefix}[{idx}]")
        elif isinstance(value, (str, bytes)):
            if not val_pattern.match(value):
                errors.append({key_prefix: f"Label value '{value}' does not match the regex {val_pattern.pattern}"})
        else:
            errors.append({key_prefix: 'expected string or bytes-like object'})

    for key, value in labels.items():
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
            continue
        if not key_pattern.match(key):
            errors.append({key: f"Label key '{key}' does not match the regex {key_pattern.pattern}"})
        _validate_value(value, key)

    if errors:
        raise ValidationError(errors)

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for key, sub_schema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Key '{key}' not found in Kubernetes response")
        value = response[key]
        if isinstance(sub_schema, dict):
            sub_last = last_applied_manifest.get(key, {})
            if not isinstance(sub_last, dict):
                sub_last = {}
            update_last_applied_manifest_dict_from_resp(sub_last, sub_schema, value)
            last_applied_manifest[key] = sub_last
        else:
            if key not in last_applied_manifest:
                last_applied_manifest[key] = value)

