def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Try to obtain the validation log from common attribute names
    log = getattr(self, 'validation_log', None)
    if log is None:
        log = getattr(self, '_validation_log', [])
    # Ensure the log is iterable
    try:
        iterator = iter(log)
    except TypeError:
        # If it's not iterable, just convert it to a string
        return f"{prefix}{str(log)}"

    lines = []
    for record in iterator:
        # Handle records that are dicts or objects with attributes
        if isinstance(record, dict):
            level = record.get('level') or record.get('type')
            message = record.get('message') or record.get('msg')
        else:
            # Try to read common attributes
            level = getattr(record, 'level', None) or getattr(record, 'type', None)
            message = getattr(record, 'message', None) or getattr(record, 'msg', None)

        # Fallback: if we cannot parse, just convert the whole record
        if level is None and message is None:
            lines.append(f"{prefix}{str(record)}")
        else:
            # Build a formatted line
            if level:
                lines.append(f"{prefix}{str(level).upper()}: {str(message)}")
            else:
                lines.append(f"{prefix}{str(message)}")

    # If there were no entries, return an empty string
    return "\n".join(lines) if lines else ""

