def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}

    # Helper to compare versions; assumes numeric versions, falls back to string compare
    def version_ge(v1, v2):
        try:
            return int(v1) >= int(v2)
        except Exception:
            return str(v1) >= str(v2)

    for logical_path, data in inventory.items():
        files = set()

        # Case 1: data is a collection of (ver, files) tuples
        if isinstance(data, (list, tuple)):
            for entry in data:
                # entry could be a tuple or dict
                if isinstance(entry, dict):
                    ver = entry.get("version")
                    file_list = entry.get("content_files", [])
                else:
                    # Assume tuple (ver, file_list)
                    if len(entry) == 2:
                        ver, file_list = entry
                    else:
                        continue
                if ver is None:
                    continue
                if version_ge(ver, version):
                    if isinstance(file_list, (list, set, tuple)):
                        files.update(file_list)
                    else:
                        files.add(file_list)

        # Case 2: data is a dict mapping version -> file list
        elif isinstance(data, dict):
            for ver, file_list in data.items():
                if version_ge(ver, version):
                    if isinstance(file_list, (list, set, tuple)):
                        files.update(file_list)
                    else:
                        files.add(file_list)

        # Case 3: data is a set/list of file paths directly
        elif isinstance(data, (set, list, tuple)):
            files.update(data)

        # Skip entries that didn't yield any files
        if files:
            result[logical_path] = files

    return result

def files_list(path):
    """
    Return the files in `path`
    """
    result = []
    for entry in os.listdir(path):
        full_path = os.path.join(path, entry)
        if os.path.isfile(full_path):
            result.append(entry)
    return result

def add_rendition(self, lang, file_path):
        """
        Register a rendition for a given language.
        The mapping will be stored internally as a dictionary where
        keys are language codes (including 'original') and values
        are file paths. Example:
            self._renditions = {
                'original': 'artigo02.pdf',
                'en': 'artigo02-en.pdf',
            }
        """
        # Ensure the renditions storage is initialized
        if not hasattr(self, "_renditions"):
            self._renditions = {}

        # Store the file path for the specified language key
        self._renditions[lang] = str(file_path)

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`."""
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            result = node.xpath(xpath)
            if result:
                first = result[0]
                if isinstance(first, str):
                    return first.strip()
                else:
                    text = first.text
                    return text.strip() if text else None
        except Exception:
            continue
    return None

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    pad = ' ' * (indent * 4)
    lines = []
    for key, val in sorted(vars(self).items()):
        if hasattr(val, 'pretty'):
            val_str = val.pretty(indent + 1, debug)
        elif isinstance(val, (list, tuple, set)):
            inner_pad = ' ' * ((indent + 1) * 4)
            items = []
            for item in val:
                if hasattr(item, 'pretty'):
                    items.append(item.pretty(indent + 2, debug))
                else:
                    items.append(repr(item))
            val_str = f'{type(val).__name__}([' + ',\n' + inner_pad + ',\n' + inner_pad + ']'
        else:
            val_str = repr(val)
        lines.append(f'{pad}    {key}={val_str}')
    content = '\n'.join(lines)
    return f'{pad}{self.__class__.__name__}(\n{content}\n{pad})'

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def _simplify(expr):
        # If expression is atomic, return it unchanged
        if not hasattr(expr, "args") or not hasattr(expr, "func"):
            return expr

        # Recursively simplify arguments
        new_args = tuple(_simplify(arg) for arg in expr.args)

        # If the expression is a logical binary operator
        if expr.func in (And, Or):
            # Ensure we work with simplified arguments
            left, right = new_args[0], new_args[1]

            # Identity: A & A or A | A -> A
            if left == right:
                return left

            # Absorption: A & (A | B) or (A | B) & A
            if expr.func is And:
                # pattern A & (A | B)
                if hasattr(right, "func") and right.func is Or:
                    if left == right.args[0] or left == right.args[1]:
                        return left
                # pattern (A | B) & A
                if hasattr(left, "func") and left.func is Or:
                    if right == left.args[0] or right == left.args[1]:
                        return right
                # Negative absorption: A & (~A | B) -> A & B
                if hasattr(right, "func") and right.func is Or:
                    # Check if left is a negation of one child of right
                    if hasattr(left, "func") and left.func is Not and right.args[0] == left.args[0]:
                        return And(left.args[0], right.args[1])
                    if hasattr(left, "func") and left.func is Not and right.args[1] == left.args[0]:
                        return And(left.args[0], right.args[0])
                if hasattr(left, "func") and left.func is Or:
                    if hasattr(right, "func") and right.func is Not and left.args[0] == right.args[0]:
                        return And(right.args[0], left.args[1])
                    if hasattr(right, "func") and right.func is Not and left.args[1] == right.args[0]:
                        return And(right.args[0], left.args[0])
            elif expr.func is Or:
                # Absorption: A | (A & B)
                if hasattr(right, "func") and right.func is And:
                    if left == right.args[0] or left == right.args[1]:
                        return left
                if hasattr(left, "func") and left.func is And:
                    if right == left.args[0] or right == left.args[1]:
                        return right
                # Negative absorption: A | (~A & B) -> A | B
                if hasattr(right, "func") and right.func is And:
                    if hasattr(left, "func") and left.func is Not and right.args[0] == left.args[0]:
                        return Or(left.args[0], right.args[1])
                    if hasattr(left, "func") and left.func is Not and right.args[1] == left.args[0]:
                        return Or(left.args[0], right.args[0])
                if hasattr(left, "func") and left.func is And:
                    if hasattr(right, "func") and right.func is Not and left.args[0] == right.args[0]:
                        return Or(right.args[0], left.args[1])
                    if hasattr(right, "func") and right.func is Not and left.args[1] == right.args[0]:
                        return Or(right.args[0], left.args[0])

            # If no absorption applied, rebuild the expression with possibly simplified args
            if new_args != expr.args:
                return expr.func(*new_args)
            return expr

        # For all other expressions, rebuild if any subexpression changed
        if new_args != expr.args:
            return expr.func(*new_args)
        return expr

    return [_simplify(arg) for arg in args]

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        # If `unicode` is not defined, we are on Python 3
        unicode
    except NameError:
        return namefunc
    def wrapper(*args, **kwargs):
        name = namefunc(*args, **kwargs)
        if isinstance(name, unicode):
            return name.encode('utf-8')
        return name
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    result = {
        'full-revisionid': None,
        'dirty': False,
        'version': '0.0.0',
    }
    try:
        # Prefer importlib.metadata if available
        from importlib.metadata import version as _im_version, PackageNotFoundError
        try:
            pkg_name = __package__ if __package__ else __name__
            result['version'] = _im_version(pkg_name)
        except PackageNotFoundError:
            # Fall back to pkg_resources
            try:
                import pkg_resources
                pkg_name = __package__ if __package__ else __name__
                result['version'] = pkg_resources.get_distribution(pkg_name).version
            except Exception:
                pass
        # Try to fetch the full git revision and dirty state if on a git repo
        try:
            import subprocess, os
            cwd = os.path.dirname(__file__) or '.'
            result['full-revisionid'] = subprocess.check_output(
                ['git', 'rev-parse', 'HEAD'],
                cwd=cwd,
                stderr=subprocess.DEVNULL
            ).decode().strip()
            status = subprocess.check_output(
                ['git', 'status', '--porcelain'],
                cwd=cwd,
                stderr=subprocess.DEVNULL
            ).decode().strip()
            result['dirty'] = bool(status)
        except Exception:
            pass
    except Exception:
        pass
    return result

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Normalize pieces to dictionary
    if isinstance(pieces, dict):
        v = pieces
    else:
        keys = ("major", "minor", "patch", "prerelease", "build")
        v = {k: pieces[i] if i < len(pieces) else "" for i, k in enumerate(keys)}

    major = str(v.get("major", "0"))
    minor = str(v.get("minor", "0"))
    patch = str(v.get("patch", "0"))
    prerelease = v.get("prerelease", "")
    build = v.get("build", "")

    # Semver style
    if style == "semver":
        base = f"{major}.{minor}.{patch}"
        result = base
        if prerelease:
            result += f"-{prerelease}"
        if build:
            result += f"+{build}"
        return result

    # PEP 440 style
    if style == "pep440":
        base = f"{major}.{minor}"
        if patch and patch != "0":
            base += f".{patch}"
        result = base
        if prerelease:
            mapping = {"alpha": "a", "beta": "b", "rc": "rc"}
            for key, val in mapping.items():
                if prerelease.startswith(key):
                    suffix = prerelease[len(key):]
                    result += f"{val}{suffix}"
                    break
        return result

    # Compact style (omit trailing zeros)
    if style == "compact":
        parts = [major]
        if minor or patch:
            parts.append(minor)
        if patch:
            parts.append(patch)
        result = ".".join(parts)
        if prerelease:
            result += f"-{prerelease}"
        if build:
            result += f"+{build}"
        return result

    # Default to full semver representation
    base = f"{major}.{minor}.{patch}"
    result = base
    if prerelease:
        result += f"-{prerelease}"
    if build:
        result += f"+{build}"
    return result

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    return "+" if "+" not in pieces else "."

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    # Store the handler function in a registry so it can be retrieved later
    if not hasattr(register_vcs_handler, "_registry"):
        register_vcs_handler._registry = {}
    register_vcs_handler._registry[vcs] = method
    return method

# The registry can be accessed via: register_vcs_handler._registry

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0
        # Determine the root directory to walk; fall back to attribute or raise.
        root_dir = getattr(self, 'root_path', getattr(self, 'storage_root', None))
        if root_dir is None:
            raise AttributeError("No root_path or storage_root attribute found for hierarchy validation.")
        for dirpath, dirnames, filenames in os.walk(root_dir):
            for filename in filenames:
                path = os.path.join(dirpath, filename)
                num_objects += 1
                valid = True
                # Validate the object if requested
                if validate_objects:
                    try:
                        if hasattr(self, 'validate_object'):
                            valid = bool(self.validate_object(path))
                        else:
                            # If no validation method, assume valid
                            valid = True
                    except Exception as e:
                        valid = False
                        if show_warnings:
                            print(f"[WARNING] Validation error for '{path}': {e}")
                # Check digest if requested
                if check_digests:
                    try:
                        if hasattr(self, 'check_digest'):
                            digest_ok = bool(self.check_digest(path))
                            if not digest_ok:
                                valid = False
                                if show_warnings:
                                    print(f"[WARNING] Digest check failed for '{path}'")
                        else:
                            # If no dedicated digest check, skip or assume OK
                            pass
                    except Exception as e:
                        valid = False
                        if show_warnings:
                            print(f"[WARNING] Digest check error for '{path}': {e}")
                if valid:
                    good_objects += 1
        return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Root inventory must already be loaded into self.root_inventory as a dict {path: digest}
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise RuntimeError("Root inventory not available or in wrong format")

    seen_paths = set()
    mismatched_digests = {}

    for vdir in version_dirs:
        inv_path = os.path.join(vdir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory.json in version directory '{vdir}'")

        with open(inv_path, "r", encoding="utf-8") as f:
            inv_data = json.load(f)

        # Handle two common inventory formats:
        # 1) a list of objects: [{ "path": "...", "digest": "..." }, ...]
        # 2) a mapping { "path": "<digest>", ... }
        if isinstance(inv_data, dict):
            current_paths = set(inv_data.keys())
            digests = inv_data
        elif isinstance(inv_data, list):
            current_paths = set()
            digests = {}
            for entry in inv_data:
                if not isinstance(entry, dict) or "path" not in entry or "digest" not in entry:
                    raise ValueError(f"Invalid inventory entry in '{inv_path}': {entry}")
                current_paths.add(entry["path"])
                digests[entry["path"]] = entry["digest"]
        else:
            raise ValueError(f"Unknown inventory structure in '{inv_path}'")

        # Ensure that this version's inventory includes all items from previous versions
        missing_earlier = seen_paths - current_paths
        if missing_earlier:
            raise ValueError(
                f"Inventory '{vdir}' missing items present in earlier versions: {sorted(missing_earlier)}"
            )

        # Update the set of seen paths
        seen_paths.update(current_paths)

        # Record mismatched digests relative to root inventory
        for path, digest in digests.items():
            root_digest = self.root_inventory.get(path)
            if root_digest is not None and root_digest != digest:
                mismatched_digests[path] = (root_digest, digest)

    # Store mismatched digests for later validation
    self.mismatched_digests = mismatched_digests
    return mismatched_digests

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not bug_ids:
        return params
    # Normalize bug_ids to an iterable
    if not isinstance(bug_ids, (list, tuple, set)):
        bug_ids = [bug_ids]
    # Convert all IDs to strings and join them with commas
    ids_str = ",".join(str(bug_id) for bug_id in bug_ids)
    # Add or append the ids to the params dictionary
    if "ids" in params:
        params["ids"] += "," + ids_str
    else:
        params["ids"] = ids_str
    return params

def deep_merge_nodes(nodes):
    '''
    Deep merge a list of (ScalarNode, value_node) tuples, handling duplicate keys.
    MappingNode values are recursively merged; otherwise, the latter value wins.
    '''
    def merge_mapping_nodes(a, b):
        # Recursively merge two MappingNode objects
        merged = []
        key_index = {}
        for i, (k, v) in enumerate(a.value):
            merged.append((k, v))
            key_index[k.value] = i
        for k_b, v_b in b.value:
            key = k_b.value
            if key in key_index:
                idx = key_index[key]
                k_a, v_a = merged[idx]
                if isinstance(v_a, MappingNode) and isinstance(v_b, MappingNode):
                    merged_value = merge_mapping_nodes(v_a, v_b)
                    merged[idx] = (k_b, merged_value)
                else:
                    merged[idx] = (k_b, v_b)
            else:
                merged.append((k_b, v_b))
                key_index[key] = len(merged) - 1
        return MappingNode(tag=a.tag, value=merged)

    merged_keys = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_keys:
            old_key_node, old_value_node = merged_keys[key]
            if isinstance(old_value_node, MappingNode) and isinstance(value_node, MappingNode):
                new_value_node = merge_mapping_nodes(old_value_node, value_node)
            else:
                new_value_node = value_node
            merged_keys[key] = (key_node, new_value_node)
        else:
            merged_keys[key] = (key_node, value_node)

    result = []
    seen = set()
    for key_node, value_node in nodes:
        key = key_node.value
        if key not in seen:
            result.append(merged_keys[key])
            seen.add(key)
    return result

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a
    space-separated string.
    """
    flags = []
    for action in parser._actions:
        flags.extend(action.option_strings)
    return " ".join(flags)

def deep_merge_nodes(nodes):
    """
    Merge a list of scalar/mapping node pairs, deep‑merging duplicate scalar keys.
    If a key appears twice with mapping values, their mappings are recursively
    merged; otherwise the latter value wins.
    """
    def _merge_mapping_nodes(a, b):
        kvs = []
        dict_vals = {}
        # Add entries from a first
        for key_node, val_node in a.value:
            kvs.append((key_node, val_node))
            dict_vals[key_node.value] = (key_node, val_node)
        # Merge entries from b
        for key_node, val_node in b.value:
            k = key_node.value
            if k in dict_vals:
                old_key_node, old_val_node = dict_vals[k]
                if isinstance(val_node, ruamel.yaml.nodes.MappingNode) and isinstance(old_val_node, ruamel.yaml.nodes.MappingNode):
                    merged_val = _merge_mapping_nodes(old_val_node, val_node)
                else:
                    merged_val = val_node
                # Replace in dict and kvs
                dict_vals[k] = (old_key_node, merged_val)
                for idx, (k_node, v_node) in enumerate(kvs):
                    if k_node.value == k:
                        kvs[idx] = (k_node, merged_val)
                        break
            else:
                kvs.append((key_node, val_node))
                dict_vals[k] = (key_node, val_node)
        return ruamel.yaml.nodes.MappingNode(tag=a.tag, value=kvs)

    seen = {}
    order = []
    for key_node, val_node in nodes:
        k = key_node.value
        if k in seen:
            old_key_node, old_val_node = seen[k]
            if isinstance(val_node, ruamel.yaml.nodes.MappingNode) and isinstance(old_val_node, ruamel.yaml.nodes.MappingNode):
                merged_val = _merge_mapping_nodes(old_val_node, val_node)
            else:
                merged_val = val_node
            seen[k] = (old_key_node, merged_val)
        else:
            seen[k] = (key_node, val_node)
            order.append(k)

    return [(seen[k][0], seen[k][1]) for k in order]

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    flags = []
    for action in parser._actions:
        if action.option_strings:
            flags.extend(action.option_strings)
    return ' '.join(flags) if flags else ''

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_namespaces = {}
    unknowns_by_parser = {}

    for name, parser in subparsers.items():
        namespace, unknown = parser.parse_known_args(unparsed_arguments)
        parsed_namespaces[name] = namespace
        unknowns_by_parser[name] = set(unknown)

    if unknowns_by_parser:
        remaining_set = set.intersection(*unknowns_by_parser.values())
    else:
        remaining_set = set()

    # Preserve original ordering of remaining arguments
    remaining_args = [arg for arg in unparsed_arguments if arg in remaining_set]

    return parsed_namespaces, remaining_args

def _dictsum(dicts):
    """Combine values of the dictionaries supplied by iterable dicts."""
    result = {}
    for d in dicts:
        for k, v in d.items():
            result[k] = result.get(k, 0) + v
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args."""
    if not url_args:
        return url
    for key, val in url_args.items():
        if val is None:
            continue
        placeholder = f"{{{key}}}"
        url = url.replace(placeholder, str(val))
    return url

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if val is None:
        return True
    if isinstance(val, str):
        cleaned = val.strip().lower()
        return cleaned in {"none", "null", "nil", "n/a", "na", ""}
    return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        # `option_strings` contains the flags for optional and positional arguments
        if getattr(action, 'option_strings', None):
            flags.extend(action.option_strings)
    return ' '.join(flags)

def was_processed(processed, path_name, verbose):
    abs_path = os.path.abspath(path_name)
    if abs_path in processed:
        if verbose:
            print(f"Already processed: {abs_path}")
        return True
    processed.add(abs_path)
    return False

def vertex3tuple(vertices):
    """Return 3-point tuples for each vertex of a closed polygon.

    For each vertex *i*, the function returns a tuple
    (previous_vertex, current_vertex, next_vertex) where
    "previous" and "next" wrap around the ends of the list.
    """
    n = len(vertices)
    if n == 0:
        return []
    return [
        (vertices[(i - 1) % n], vertices[i], vertices[(i + 1) % n])
        for i in range(n)
    ]

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("Number must be non-negative")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two symbols")
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while number:
            number, rem = divmod(number, base)
            digits.append(alphabet[rem])
    result = ''.join(reversed(digits))
    if padding is not None and padding > len(result):
        pad_len = padding - len(result)
        result = alphabet[0] * pad_len + result
    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    def _recurse(obj):
        if isinstance(obj, dict):
            for key, value in list(obj.items()):
                if key == register_value:
                    obj[key] = register_number
                else:
                    _recurse(value)
        elif isinstance(obj, list):
            for item in obj:
                _recurse(item)
        # For any other data types (int, str, etc.), no action is needed

    _recurse(flow_params)
    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    return value.replace('.', arg)

def string_to_int(string: str, alphabet: List[str]) -> int:
    if not string:
        return 0
    base = len(alphabet)
    char_to_value = {c: i for i, c in enumerate(alphabet)}
    number = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' not in alphabet")
        number = number * base + char_to_value[ch]
    return number

def unquote(name):
    """Remove quote from the given name."""
    if isinstance(name, str):
        if len(name) >= 2 and ((name[0] == name[-1]) and name[0] in ("'", '"', "`")):
            return name[1:-1]
    return name

import os, shlex

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0
    if platform == 1:
        return shlex.split(s, posix=True)
    elif platform == 0:
        return shlex.split(s, posix=False)
    else:
        raise ValueError(f"Unsupported platform: {platform}")

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    result = subprocess.run(['git', 'ls-files', '-i', '--exclude-standard'], capture_output=True, text=True)
    files = result.stdout.splitlines()
    files.sort()
    return ','.join(files)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".
    For instance, given "3 weeks", return datetime.timedelta(weeks=3)
    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq = frequency.strip()
    if not freq or freq.lower() == 'always':
        return None

    import re
    match = re.fullmatch(r'(\d+)\s*([a-zA-Z]+)', freq.lower())
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency!r}")
    amount = int(match.group(1))
    unit = match.group(2)

    kwargs = {}
    if unit in {'second', 'seconds', 'sec', 'secs'}:
        kwargs['seconds'] = amount
    elif unit in {'minute', 'minutes', 'min', 'mins'}:
        kwargs['minutes'] = amount
    elif unit in {'hour', 'hours', 'hr', 'hrs'}:
        kwargs['hours'] = amount
    elif unit in {'day', 'days'}:
        kwargs['days'] = amount
    elif unit in {'week', 'weeks'}:
        kwargs['weeks'] = amount
    elif unit in {'month', 'months'}:
        kwargs['days'] = amount * 30  # approximate month as 30 days
    elif unit in {'year', 'years'}:
        kwargs['days'] = amount * 365  # approximate year as 365 days
    else:
        raise ValueError(f"Unknown time unit: {unit}")
    return datetime.timedelta(**kwargs)

def make_find_paths(find_paths):
    result = []
    for part in find_paths:
        # Pass through if it's already a pattern (contains a colon or glob meta-characters)
        if ':' in part or re.search(r'[\*\?\[\]]', part):
            result.append(part)
        else:
            # Convert ordinary path fragments into a sh glob pattern
            result.append(f"sh:**/*{part}*/**")
    return result

def oneline(script, separator=" && "):
    """Convert a multi‑line script into a single‑line command suitable for SSH."""
    if not script:
        return ""
    # Normalize indentation
    dedented = textwrap.dedent(script)
    # Remove leading/trailing whitespace and skip empty lines
    lines = [line.strip() for line in dedented.splitlines() if line.strip()]
    # Join the cleaned lines with the specified separator
    return separator.join(lines)

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if strip:
        pattern = pattern.strip()
    # Escape any regex metacharacters to treat the pattern as a literal string
    escaped = re.escape(pattern)
    # Compile the escaped pattern for efficient matching
    return re.compile(escaped)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the full command list
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        cmd = [commands]
    if args:
        # If args is a list/tuple, extend; otherwise, treat as single string
        if isinstance(args, (list, tuple)):
            cmd.extend(args)
        else:
            cmd.append(args)
    if verbose:
        print("Running command:", " ".join(cmd))
    # Set up subprocess run parameters
    run_kwargs = {
        "cwd": cwd,
        "env": env,
        "text": True,
    }
    if hide_stderr:
        run_kwargs["stdout"] = subprocess.PIPE
        run_kwargs["stderr"] = subprocess.DEVNULL
    else:
        run_kwargs["capture_output"] = True
    try:
        result = subprocess.run(cmd, **run_kwargs)
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd[0]}") from e
    return result

def is_ipv4(target):
    """Test if IPv4 address or not."""
    try:
        return isinstance(ipaddress.ip_address(str(target)), ipaddress.IPv4Address)
    except (ValueError, TypeError):
        return False

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is None:
        dumper = yaml.SafeDumper
    result = yaml.dump(
        obj,
        Dumper=dumper,
        default_flow_style=False,
        allow_unicode=True,
    )
    if isinstance(result, bytes):
        result = result.decode("utf-8")
    return result

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    log_records = []
    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                content = f.read()
            # Attempt to parse the configuration as a Python literal (dictionary)
            config = eval(content, {"__builtins__": None}, {})
            if not isinstance(config, dict):
                raise ValueError("Parsed configuration is not a dictionary")
        except Exception as exc:
            record = logging.LogRecord(
                "config_loader",
                logging.ERROR,
                fname,
                0,
                f"Error parsing '{fname}': {exc}",
                None,
                None
            )
            log_records.append(record)
            continue

        # Resolve environment variables in string values if requested
        if resolve_env:
            try:
                import os
                for key, value in config.items():
                    if isinstance(value, str):
                        # Replace occurrences of $VAR or ${VAR} with environment value
                        import re
                        pattern = r'\$(\w+)|\${(\w+)}'
                        def repl(match):
                            var_name = match.group(1) or match.group(2)
                            return os.getenv(var_name, match.group(0))
                        new_value = re.sub(pattern, repl, value)
                        config[key] = new_value
            except Exception:
                # Ignore any failures during env resolution
                pass

        # Apply overrides if supplied
        if overrides and isinstance(overrides, dict):
            for key, override_value in overrides.items():
                if key in config:
                    config[key] = override_value

        configs[fname] = config

    return configs, log_records

def force_string(obj):
    if isinstance(obj, str):
        return obj.encode('utf-8')
    return obj

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """

        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol_version must be a tuple")
            handler = cls._handlers.get(protocol_version)
            return {protocol_version: handler} if handler else {}
        # Return a copy of all handlers if no specific version requested
        return dict(cls._handlers)

@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        return cls(values=list(values))

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type)."""
    from collections.abc import Sequence, Mapping
    # If seq is a mapping (e.g., dict), use its values as the sequence
    if isinstance(seq, Mapping):
        seq = seq.values()
    # Handle byte-like objects separately (bytes, bytearray) – treat them as a single sequence
    if isinstance(seq, (bytes, bytearray)):
        return seq, type(seq)
    # For plain strings, convert to a list of characters (keeping the original type returned)
    if isinstance(seq, str):
        return list(seq), type(seq)
    # If seq is already a Sequence (e.g., list, tuple, range), return it unchanged
    if isinstance(seq, Sequence):
        return seq, type(seq)
    # For any other iterable, materialise it into a list
    try:
        seq_list = list(seq)
        return seq_list, type(seq_list)
    except TypeError:
        # seq is not iterable – wrap it in a list to provide a sequence
        return [seq], type([seq])

def _verify(iface, candidate, tentative=False, vtype=None):
    """Verify that *candidate* might correctly provide *iface*."""
    errors = []

    # 1. Check that candidate claims to provide the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    f"{candidate!r} does not provide {iface.__name__}"
                )
        except Exception as exc:
            errors.append(
                f"Error checking providedBy for {candidate!r} and {iface.__name__}: {exc}"
            )

    # 2. Check methods and attributes
    for name, val in iface.items():
        is_method = getattr(val, "_isMethod", False)
        is_attribute = getattr(val, "_isAttribute", False) or getattr(val, "_isProperty", False)

        # Skip non-method/non-attribute members
        if not (is_method or is_attribute):
            continue

        # Does candidate define the member?
        if not hasattr(candidate, name):
            errors.append(f"{candidate!r} is missing member {name!r}")
            continue

        # If it's a method, check signature
        if is_method:
            candidate_method = getattr(candidate, name)
            if not callable(candidate_method):
                errors.append(f"{candidate!r}.{name!r} is not callable")
                continue
            try:
                iface_sig = inspect.signature(val)
                cand_sig = inspect.signature(candidate_method)
            except Exception as exc:
                errors.append(
                    f"Error inspecting signatures for {candidate!r}.{name!r}: {exc}"
                )
                continue
            # Compare parameter names and kind
            iface_params = list(iface_sig.parameters)
            cand_params = list(cand_sig.parameters)
            if len(iface_params) != len(cand_params):
                errors.append(
                    f"Signature mismatch for {candidate!r}.{name!r}: expected {iface_sig}, got {cand_sig}"
                )
                continue
            for i, (ip, cp) in enumerate(zip(iface_params, cand_params)):
                ip_obj = iface_sig.parameters[ip]
                cp_obj = cand_sig.parameters[cp]
                if ip_obj.kind != cp_obj.kind or ip_obj.default is not cp_obj.default:
                    errors.append(
                        f"Parameter mismatch in {candidate!r}.{name!r} at position {i+1}: expected {ip_obj}, got {cp_obj}"
                    )
                    break

    # 3. Report errors
    if not errors:
        return True
    if len(errors) == 1:
        raise zope.interface.Invalid(errors[0])
    raise zope.interface.Invalid("; ".join(errors))

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # If candidate is a class, check subclass relationship
    if isinstance(candidate, type):
        try:
            if issubclass(candidate, iface):
                return True
        except Exception:
            # If iface is not a class or other error occurs, treat as tentative
            pass
        return tentative
    # If candidate is an instance, check instance relationship
    try:
        if isinstance(candidate, iface):
            return True
    except Exception:
        # If iface is not usable with isinstance, treat as tentative
        pass
    return tentative

def determineMetaclass(bases, explicit_mc=None):
    """
    Determine metaclass from one or more base classes and an optional explicit __metaclass__.
    Mimics the logic of Python's type.__new__ when creating a new class.
    """
    # Start with the explicit metaclass if one is provided
    if explicit_mc is not None:
        mc = explicit_mc
    else:
        # If no explicit metaclass, use the metaclass of the first base
        # or the default type if there are no bases
        if bases:
            mc = type(bases[0])
        else:
            mc = type

    # Resolve any conflicts between the metaclasses of the bases
    for base in bases:
        base_meta = type(base)
        if mc is None:
            mc = base_meta
            continue

        # If the metaclasses are mutually incompatible, raise an error
        if not issubclass(base_meta, mc) and not issubclass(mc, base_meta):
            raise TypeError(
                f"metaclass conflict: {mc.__name__} vs {base_meta.__name__}"
            )

        # Prefer the more derived metaclass
        if issubclass(base_meta, mc):
            mc = base_meta

    return mc

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    del self[key]
    return value

def popitem(self):
        """Remove and return the `(key, value)` pair least recently used."""
        try:
            return self._cache.popitem(last=False)
        except KeyError:
            raise KeyError("dictionary is empty") from None

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter."""
    # Determine the parameter style, defaulting to "named" if not set
    paramstyle = getattr(self, "_paramstyle", "named")
    # Instantiate and return the converter for the specified style
    return _converting._Converter(paramstyle)

def isoparse(self, dt_str):
    """
    Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

    See the original documentation for supported formats.

    """
    # Accept a file-like object
    if hasattr(dt_str, "read"):
        dt_str = dt_str.read()
    s = dt_str.strip()
    if not s:
        raise ValueError("empty datetime string")

    # separate date and optional time part
    if "T" in s:
        date_part, rest = s.split("T", 1)
    else:
        date_part, rest = s, ""

    # ---------- date part ----------
    if "W" in date_part or "w" in date_part:
        # ISO week dates
        # full form: YYYY-Www-D or YYYY-Www
        m = re.match(r"^(\d{4})[-]?([Ww])(\d{2})[-]?(\d)?$", date_part)
        if not m:
            raise ValueError("invalid ISO week date: %s" % date_part)
        year = int(m.group(1))
        week = int(m.group(3))
        day = int(m.group(4)) if m.group(4) else 1  # default to Monday
        try:
            date_obj = datetime.date.fromisocalendar(year, week, day)
        except Exception:
            raise ValueError("invalid ISO week date: %s" % date_part)
    else:
        # year-month-day type
        if "-" in date_part:
            parts = date_part.split("-")
            year = int(parts[0]) if parts[0] else 1
            month = int(parts[1]) if len(parts) > 1 and parts[1] else 1
            day = int(parts[2]) if len(parts) > 2 and parts[2] else 1
        else:
            # zero‑separated form, e.g. 20170928
            if len(date_part) >= 4:
                year = int(date_part[0:4])
            else:
                year = 1
            if len(date_part) >= 6:
                month = int(date_part[4:6])
            else:
                month = 1
            if len(date_part) >= 8:
                day = int(date_part[6:8])
            else:
                day = 1
        date_obj = datetime.date(year, month, day)

    # ---------- time part ----------
    tzinfo = None
    if rest:
        # Extract timezone component
        tz_match = re.search(r"(Z|[+-]\d{2}:\d{2}|[+-]\d{4}|[+-]\d{2})$", rest)
        if tz_match:
            tz_str = tz_match.group(0)
            rest_time = rest[:-len(tz_str)]
            if tz_str == "Z" or tz_str in ("+00:00", "+0000", "+00"):
                tzinfo = tzutc()
            else:
                sign = 1 if tz_str[0] == "+" else -1
                if ":" in tz_str:
                    h, m_ = tz_str[1:].split(":")
                elif len(tz_str) == 5:
                    h, m_ = tz_str[1:3], tz_str[3:5]
                else:
                    h, m_ = tz_str[1:], "00"
                hours = int(h)
                minutes = int(m_)
                offset_seconds = sign * (hours * 3600 + minutes * 60)
                tzinfo = tzoffset(None, offset_seconds)
        else:
            rest_time = rest

        # parse time and fractional seconds
        if rest_time.startswith("24:"):
            hour = 24
            rest_time = rest_time[3:]
        else:
            # pattern: hh[:mm[:ss]][.{fractions}]
            m = re.match(r"^(\d{2})(?::?(\d{2})?)(?::?(\d{2})?)?([.,]\d{1,6})?$", rest_time)
            if not m:
                raise ValueError("invalid time part: %s" % rest_time)
            hour = int(m.group(1))
            minute = int(m.group(2)) or 0
            second = int(m.group(3)) or 0
            frac = m.group(4)
            micro = 0
            if frac:
                frac_digits = frac[1:].rjust(6, "0")
                micro = int(frac_digits[:6])

        # handle 24:00 case
        if hour == 24:
            hour = 0
            date_obj = date_obj + datetime.timedelta(days=1)

        dt = datetime.datetime(
            date_obj.year, date_obj.month, date_obj.day,
            hour, minute, second, micro, tzinfo=tzinfo
        )
    else:
        dt = datetime.datetime(date_obj.year, date_obj.month, date_obj.day, 0, 0, 0, 0, tzinfo=tzinfo)

    return dt

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # 1. Check for common Diaspora headers that are used in both public and private feeds
    if request.headers.get("X-Diaspora-Endpoint") or request.headers.get("X-Diaspora-Feed"):
        return True

    # 2. Check for private message specific header
    if request.headers.get("X-Diaspora-Secret"):
        return True

    # 3. Check body or form data for legacy payload markers
    payload = None
    # Attempt to read JSON body
    if hasattr(request, "get_json"):
        try:
            payload = request.get_json(silent=True)
        except Exception:
            pass

    # Fallback to form data or query string if JSON was not present
    if not payload and hasattr(request, "form"):
        payload = request.form
    if not payload and hasattr(request, "args"):
        payload = request.args

    if isinstance(payload, dict):
        # Legacy payloads often contain a "legacy" key or a specific key used by Diaspora
        if "legacy" in payload or "diaspora" in payload or payload.get("type") == "diaspora":
            return True

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # 1. Check for common Matrix API path prefixes
        if hasattr(request, "path") and isinstance(request.path, str):
            path = request.path.lower()
            if path.startswith("/_matrix") or "/_matrix" in path:
                return True

        # 2. Check for Matrix in the URL
        if hasattr(request, "url"):
            url = request.url
            if isinstance(url, str) and "/_matrix" in url:
                return True
            # Some URL objects expose a path attribute
            try:
                if isinstance(getattr(url, "path", ""), str) and "/_matrix" in getattr(url, "path", ""):
                    return True
            except Exception:
                pass

        # 3. Look for Matrix specific headers
        if hasattr(request, "headers") and isinstance(request.headers, dict):
            for key in request.headers:
                if "matrix" in key.lower():
                    return True

        return False
    except Exception:
        # Any unexpected error leads to a conservative "not a Matrix request" outcome
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    D* nodes use ISO 8601 UTC timestamps (e.g. "2023-03-17T12:30:00Z").
    If a naive datetime or string without timezone information is provided,
    it is assumed to be UTC.  Strings are parsed with
    `dateutil.parser.isoparse` if available, otherwise
    `datetime.fromisoformat` is used.
    """
    from datetime import datetime, timezone
    # Handle string input
    if isinstance(dt, str):
        try:
            import dateutil.parser
            dt_val = dateutil.parser.isoparse(dt)
        except Exception:
            # fallback to built‑in parsing (Python 3.7+)
            dt_val = datetime.fromisoformat(dt)
    else:
        dt_val = dt

    # Ensure we have a datetime instance
    if isinstance(dt_val, datetime):
        dt_obj = dt_val
    else:
        # Unsupported type – raise a helpful error
        raise TypeError("Input must be a datetime or string representation")

    # Convert to UTC
    if dt_obj.tzinfo is None:
        dt_utc = dt_obj.replace(tzinfo=timezone.utc)
    else:
        dt_utc = dt_obj.astimezone(timezone.utc)

    # Return ISO 8601 string with trailing Z
    return dt_utc.strftime('%Y-%m-%dT%H:%M:%SZ')

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        response = requests.head(url, allow_redirects=True, timeout=10)
        return response.headers.get('Content-Type')
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    stripped = tag.strip()
    if not stripped:
        return False
    if len(stripped) > 50:
        return False
    return all(c.isalnum() or c in '-_' for c in stripped)

def xml_children_as_dict(node):
    """Turn the children of node `<xml>` into a dict, keyed by tag name.

    This is only a shallow conversion – child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        # Remove namespace if present
        tag = child.tag
        if tag.startswith('{'):
            tag = tag.split('}', 1)[-1]
        result[tag] = child
    return result

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        doc_tree = etree.fromstring(doc.encode('utf-8'))
    except Exception as e:
        raise ValueError(f"Invalid XML document: {e}")

    # Find the Signature element
    signed_info = doc_tree.find('.//{http://www.w3.org/2000/09/xmldsig#}Signature')
    if signed_info is None:
        raise ValueError("No Signature element found in the document")

    # Compare SignatureValue with provided signature if provided
    if signature:
        sig_value_node = signed_info.find('.//{http://www.w3.org/2000/09/xmldsig#}SignatureValue')
        if sig_value_node is None:
            raise ValueError("SignatureValue element missing from Signature")
        if sig_value_node.text.strip() != signature.strip():
            return False

    # Setup the signature context
    ctx = xmlsec.SignatureContext()
    try:
        key = xmlsec.Key.from_memory(public_key, xmlsec.constants.KeyDataFormatCertPem)
    except Exception as e:
        raise ValueError(f"Failed to load public key: {e}")

    ctx.key = key

    # Verify the signature
    try:
        ctx.verify(signed_info)
        return True
    except xmlsec.VerificationError:
        return False
    except Exception as e:
        raise ValueError(f"Signature verification failed: {e}")

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Attempt JSON parsing first
    try:
        data = json.loads(document)
        if isinstance(data, dict) and 'subject' in data:
            # Ensure aliases is a list
            aliases = data.get('aliases')
            if aliases is None:
                data['aliases'] = []
            elif not isinstance(aliases, list):
                data['aliases'] = [aliases]
            # Ensure links is a list
            links = data.get('links')
            if links is None:
                data['links'] = []
            elif not isinstance(links, list):
                data['links'] = [links]
            return data
    except json.JSONDecodeError:
        pass

    # If not JSON, try XRD parsing
    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        # If parsing fails, return empty dict
        return {}

    def localname(tag: str) -> str:
        return tag.split('}', 1)[-1] if '}' in tag else tag

    subject = None
    aliases: list[str] = []
    links: list[dict] = []

    for elem in root.iter():
        tag = localname(elem.tag)
        if tag == 'Subject':
            if elem.text:
                subject = elem.text.strip()
        elif tag == 'Alias':
            if elem.text:
                alias = elem.text.strip()
                if alias:
                    aliases.append(alias)
        elif tag == 'Link':
            rel = elem.attrib.get('rel')
            href = elem.attrib.get('href')
            link_dict: dict[str, str] = {}
            if rel:
                link_dict['rel'] = rel
            if href:
                link_dict['href'] = href
            # Include any additional attributes
            for k, v in elem.attrib.items():
                if k not in ('rel', 'href'):
                    link_dict[k] = v
            links.append(link_dict)

    return {'subject': subject, 'aliases': aliases, 'links': links}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        _, domain = handle.split("@", 1)
        if not domain:
            return None
    except ValueError:
        return None

    url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"
    try:
        response = requests.get(url, timeout=5)
        if response.status_code == 200:
            return response.text
    except Exception:
        pass
    return None

def retrieve_and_parse_diaspora_webfinger(handle):
    import urllib.request, urllib.parse, urllib.error, json

    if '@' not in handle:
        raise ValueError("Handle must be in the form user@example.com")
    resource = f"acct:{handle}"
    encoded_resource = urllib.parse.quote(resource, safe='')
    host = handle.split('@', 1)[1]
    url = f"https://{host}/.well-known/webfinger?resource={encoded_resource}"
    request = urllib.request.Request(url, headers={"Accept": "application/jrd+json"})

    try:
        with urllib.request.urlopen(request, timeout=10) as response:
            if response.status != 200:
                raise ValueError(f"Failed to retrieve webfinger document. HTTP status: {response.status}")
            body = response.read().decode('utf-8')
            return json.loads(body)
    except urllib.error.HTTPError as e:
        raise ValueError(f"HTTPError retrieving webfinger: {e}") from e
    except urllib.error.URLError as e:
        raise ValueError(f"URLError retrieving webfinger: {e}") from e
    except json.JSONDecodeError as e:
        raise ValueError(f"Failed to parse JSON from webfinger response: {e}") from e

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """
    Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    import requests
    try:
        # Use the generic request function to support any HTTP method
        response = requests.request(method=method, url=url, data=data, timeout=timeout, *args, **kwargs)
        # If the request was successful (no exception raised), return status code and None for error
        return (response.status_code, None)
    except requests.exceptions.RequestException as exc:
        # On any request-related error, return None for the status code and the exception instance
        return (None, exc)
    except Exception as exc:
        # Catch any unexpected exception and return it similarly
        return (None, exc)

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments
    """
    keys_chain = [key] + list(keys)
    cur = dic
    for k in keys_chain[:-1]:
        if k not in cur or not isinstance(cur[k], dict):
            cur[k] = {}
        cur = cur[k]
    cur[keys_chain[-1]] = val
    return dic

def list_of_file_names(settings_dirs, spec_option):
    """
    Create a new IniType complex type
    """
    import os
    if isinstance(settings_dirs, str):
        settings_dirs = [settings_dirs]
    files = []
    for d in settings_dirs:
        if not os.path.isdir(d):
            continue
        for entry in os.listdir(d):
            full_path = os.path.join(d, entry)
            if os.path.isfile(full_path):
                if spec_option:
                    # if spec_option is a file extension like '.ini'
                    if entry.lower().endswith(spec_option.lower()):
                        files.append(full_path)
                else:
                    files.append(full_path)
    return sorted(files)

