@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("No spec content provided")

        try:
            data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"Failed to parse YAML: {exc}") from exc

        if not isinstance(data, dict):
            raise IRValidatorException("Spec content must be a dictionary at top level")

        required_fields = ["name", "version", "spec"]
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(f"Missing mandatory fields: {', '.join(missing)}")

        return data

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if not yaml_file:
        raise IRValidatorException('yaml_file path not provided.')

    try:
        with open(yaml_file, 'r', encoding='utf-8') as f:
            data = yaml.safe_load(f)
    except FileNotFoundError:
        raise IRValidatorException(f'YAML file not found: {yaml_file}')
    except Exception as e:
        raise IRValidatorException(f'Error loading YAML file: {e}')

    if not isinstance(data, dict):
        raise IRValidatorException('YAML file does not contain a mapping at top level.')

    # Validate mandatory fields if defined
    required_fields = getattr(cls, 'required_fields', None)
    if required_fields:
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(
                f'Missing mandatory fields in YAML file: {", ".join(missing)}'
            )

    return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Pull defaults directly from the specification
    spec = getattr(self, "spec", {})
    for name, spec_item in spec.items():
        if isinstance(spec_item, dict):
            defaults[name] = spec_item.get("default")
        else:
            defaults[name] = spec_item
    # Override with any attributes of the instance that match a spec key
    for key in list(defaults.keys()):
        if hasattr(self, key):
            defaults[key] = getattr(self, key)
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    # Deprecated options mapped to their replacements
    # Example:
    #     'old_option': 'new_option',
    return {}

def get_parser_option_specs(self, command_name):
        """Gets all the options for the specified command

        :param command_name: the command name (main, virsh, ospd, etc...)
        :return: the list of all command options
        """
        # Retrieve the parser instance for the requested command
        parser, _ = self._get_parser_and_labels(command_name)

        # If the parser exposes a dedicated method to list its option specs, use it
        if hasattr(parser, 'get_option_specs'):
            return parser.get_option_specs()

        # Fall back to inspecting the parser's attributes (common with argparse/Click)
        if hasattr(parser, 'option_specifiers'):
            return parser.option_specifiers

        # If it's an argparse.Namespace, return its dict of attributes
        if hasattr(parser, '__dict__') and hasattr(parser, 'parse_known_args'):
            return vars(parser)

        # Unable to determine options format
        raise AttributeError(f"Parser for command '{command_name}' does not expose option specs.")

def get_silent_args(self, args):
    """
    Return the names of arguments that are considered "silent" – i.e. those
    whose value is either None, False, an empty string, or otherwise falsy.
    The input `args` may be a mapping or an object with attributes.
    """
    silent = []

    # If args is a dictionary-like object, iterate over items.
    if isinstance(args, dict):
        for key, value in args.items():
            if value in (None, False, ""):
                silent.append(key)
        return silent

    # Otherwise, treat args as an object and inspect its attributes.
    for attr in dir(args):
        if attr.startswith("_"):
            continue
        try:
            value = getattr(args, attr)
        except AttributeError:
            continue
        if value in (None, False, ""):
            silent.append(attr)

    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")
    required = getattr(self, 'required', getattr(self, 'requires', []))
    missing = [name for name in required if name not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec: the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    conditionally_required = []

    for opt in options_spec:
        opt_name = opt.get('name')
        if not opt_name:
            continue

        required_when = opt.get('required_when')
        if required_when is None:
            continue

        matched = False
        try:
            if callable(required_when):
                # If it's a function, call it with args
                matched = bool(required_when(args))
            elif isinstance(required_when, dict):
                # All key/value pairs must match the current args
                matched = True
                for key, value in required_when.items():
                    if isinstance(value, bool):
                        # value True means key must be present, False means absent
                        if value and key not in args:
                            matched = False
                            break
                        if not value and key in args:
                            matched = False
                            break
                    else:
                        if args.get(key) != value:
                            matched = False
                            break
            elif isinstance(required_when, (list, tuple)):
                # All items in the list must evaluate to True
                matched = all(self._get_conditionally_required_args(
                    command_name, [{'name': key, 'required_when': cond}], args
                ) for key, cond in required_when)
            elif isinstance(required_when, str):
                # Treat string as a flag that must be present
                matched = required_when in args or args.get(required_when) is not None
            else:
                # Fallback: any truthy value means requirement applies
                matched = bool(required_when)
        except Exception:
            matched = False

        if matched:
            conditionally_required.append(opt_name)

    return conditionally_required

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for key, value in args.items():
        if key in getattr(self, "choices", {}):
            allowed = self.choices[key]
            if isinstance(value, (list, tuple, set)):
                for item in value:
                    if item not in allowed:
                        raise ValueError(
                            f"Invalid choice for '{key}': {item}. "
                            f"Allowed choices are: {allowed}"
                        )
            else:
                if value not in allowed:
                    raise ValueError(
                        f"Invalid choice for '{key}': {value}. "
                        f"Allowed choices are: {allowed}"
                    )

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dict")
    class ComplexArgument:
        def __init__(self, value):
            if spec_option.get('required', False) and value is None:
                raise ValueError(f"The option '{option_name}' is required for subcommand '{subcommand}'")
            if 'convert' in spec_option and callable(spec_option['convert']):
                try:
                    value = spec_option['convert'](value)
                except Exception as exc:
                    raise ValueError(f"Failed to convert option '{option_name}' for subcommand '{subcommand}': {exc}")
            if 'choices' in spec_option:
                if value not in spec_option['choices']:
                    raise ValueError(f"Invalid value '{value}' for option '{option_name}'. Allowed: {spec_option['choices']}")
            self.value = value
            self.description = spec_option.get('help', '')
            self.choices = spec_option.get('choices')
        def __repr__(self):
            return f"<{type_name} value={self.value!r}>"
        def __eq__(self, other):
            return isinstance(other, ComplexArgument) and self.value == other.value
    default = spec_option.get('default')
    return ComplexArgument(default)

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Prepare dictionaries for the three categories
    control_args = {}
    nested_args = {}
    custom_args = {}

    # Normalize args into an iterable of (key, value) pairs
    if isinstance(args, dict):
        items = list(args.items())
    else:
        items = []
        for item in args:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                items.append((str(item[0]), item[1]))
            elif isinstance(item, str) and '=' in item:
                key, val = item.split('=', 1)
                items.append((key, val))
            else:
                # Treat as a flag (True)
                items.append((str(item), True))

    # Classify each argument
    for key, value in items:
        # Control arguments: explicit prefix or common flag names
        if key.startswith('control_') or key in ('debug', 'check', 'quiet'):
            control_args[key] = value
        # Custom arguments: explicit prefix
        elif key.startswith('custom_'):
            custom_args[key] = value
        # Otherwise nested arguments
        else:
            nested_args[key] = value

    # Merge custom arguments into nested; custom variables override nested values
    nested_args.update(custom_args)

    return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars in the form ``key=value`` or a dictionary
    :return: The updated dictionary
    """
    if not isinstance(vars_dict, dict):
        return vars_dict
    if not extra_vars:
        return vars_dict

    for item in extra_vars:
        # Handle dict inputs directly
        if isinstance(item, dict):
            vars_dict.update(item)
        elif isinstance(item, str):
            if '=' in item:
                key, value = item.split('=', 1)
                key = key.strip()
                value = value.strip()
                # Attempt to evaluate Python literals for nicer types
                try:
                    import ast
                    parsed_value = ast.literal_eval(value)
                except Exception:
                    parsed_value = value
                vars_dict[key] = parsed_value
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # A mapping of parser_name to a dict of parameter names and the desired type.
        # This should be defined elsewhere in the class; use an empty dict if unavailable.
        type_map = getattr(self, '_arg_type_map', {})
        parser_map = type_map.get(parser_name, {})

        # In-place conversion to avoid modifying the dictionary during iteration
        for key, val in list(values_dict.items()):
            target_type = parser_map.get(key)
            if not target_type:
                continue  # no conversion defined for this key

            try:
                if target_type is bool:
                    if isinstance(val, str):
                        # Treat common truthy/falsey strings
                        values_dict[key] = val.lower() in ("true", "1", "yes", "y", "on")
                    else:
                        values_dict[key] = bool(val)
                elif target_type is list:
                    if isinstance(val, str):
                        # Split commas and strip whitespace, ignore empty items
                        values_dict[key] = [item.strip() for item in val.split(",") if item.strip()]
                    else:
                        # Ensure it's a list
                        values_dict[key] = list(val)
                else:
                    # For int, float, str, or any callable type
                    values_dict[key] = target_type(val)
            except Exception:
                # If conversion fails, keep the original string value
                pass

        return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec.

    Looks for a spec file named 'spec.yaml', 'spec.yml', or 'spec.json' inside the given
    plugin directory. The file is parsed with PyYAML or the standard json module
    and the resulting structure is flattened into a single‑level dictionary where
    nested keys are joined with a dot ('.').  Lists are flattened by index.

    :param plugin_dir: A path to the plugin's directory.
    :return: A flat dictionary containing the plugin's properties.
    """
    from pathlib import Path
    import json

    try:
        import yaml
    except Exception:
        yaml = None

    plugin_path = Path(plugin_dir)
    spec_file = None

    for fname in ("spec.yaml", "spec.yml", "spec.json"):
        candidate = plugin_path / fname
        if candidate.is_file():
            spec_file = candidate
            break

    if not spec_file:
        return {}

    with spec_file.open("r", encoding="utf-8") as f:
        if spec_file.suffix in {".yaml", ".yml"} and yaml:
            data = yaml.safe_load(f)
        else:
            data = json.load(f)

    def _flatten(value, prefix=""):
        """
        Recursively flatten a nested dictionary or list.
        Keys in dictionaries are joined with '.', lists are indexed.
        """
        items = {}

        if isinstance(value, dict):
            for k, v in value.items():
                key = f"{prefix}.{k}" if prefix else k
                items.update(_flatten(v, key))
        elif isinstance(value, list):
            for idx, v in enumerate(value):
                key = f"{prefix}.{idx}" if prefix else str(idx)
                items.update(_flatten(v, key))
        else:
            items[prefix] = value

        return items

    return _flatten(data if isinstance(data, (dict, list)) else {})
